const { body, param } = require('express-validator');

exports.create = [
  // SKU is generated by the server when the client does not send one.
  body('sku').optional({ values: 'falsy' }).trim().isLength({ max: 50 }),
  body('name').trim().isLength({ min: 2, max: 150 }).withMessage('Product name is required'),
  body('sellingPrice').isFloat({ min: 0 }).withMessage('Selling price must be 0 or more'),
  body('costPrice').optional().isFloat({ min: 0 }).withMessage('Cost price must be 0 or more'),
  body('stockQuantity').optional().isInt({ min: 0 }).withMessage('Stock must be a whole number, 0 or more'),
  body('lowStockThreshold').optional().isInt({ min: 0 }),
  body('categoryId').optional({ values: 'null' }).isInt({ min: 1 }),
  body('barcode').optional({ values: 'falsy' }).trim().isLength({ max: 64 }),
  body('unit').optional().trim().isLength({ max: 20 }),
  body('expiryDate').optional({ values: 'null' }).isISO8601().withMessage('Expiry date must be YYYY-MM-DD'),
  body('expiryWarningDays').optional().isInt({ min: 0, max: 365 })
    .withMessage('Warning days must be between 0 and 365'),
];

exports.update = [
  param('id').isInt({ min: 1 }),
  body('sku').optional().trim().isLength({ min: 1, max: 50 }),
  body('name').optional().trim().isLength({ min: 2, max: 150 }),
  body('sellingPrice').optional().isFloat({ min: 0 }),
  body('costPrice').optional().isFloat({ min: 0 }),
  body('lowStockThreshold').optional().isInt({ min: 0 }),
  body('categoryId').optional({ values: 'null' }).isInt({ min: 1 }),
  body('isActive').optional().isBoolean(),
  body('expiryDate').optional({ values: 'null' }).isISO8601().withMessage('Expiry date must be YYYY-MM-DD'),
  body('expiryWarningDays').optional().isInt({ min: 0, max: 365 }),
];

exports.adjustStock = [
  param('id').isInt({ min: 1 }),
  body('changeType').isIn(['restock', 'adjustment', 'return']).withMessage("changeType must be restock, adjustment or return"),
  body('quantityChange').isInt().custom((v) => Number(v) !== 0).withMessage('quantityChange must be a non-zero whole number'),
  body('note').optional({ values: 'falsy' }).trim().isLength({ max: 255 }),
  // Only used when adding stock: a delivery can carry its own date and lot number.
  body('expiryDate').optional({ values: 'null' }).isISO8601().withMessage('Expiry must be YYYY-MM-DD'),
  body('batchNo').optional({ values: 'falsy' }).trim().isLength({ max: 40 }),
  body('costPrice').optional().isFloat({ min: 0 }),
];

exports.writeOff = [
  param('id').isInt({ min: 1 }),
  body('quantity').optional().isInt({ min: 1 }).withMessage('Quantity must be a positive whole number'),
  body('note').optional({ values: 'falsy' }).trim().isLength({ max: 255 }),
];

exports.idParam = [param('id').isInt({ min: 1 }).withMessage('Invalid id')];
